mapper.select:
SELECT t.`rel_id` as id, t.`pri_table_id` as primaryTableId, t.`sub_table_id` as subTableId, pri.`table_name` as primaryTableName, sub.`table_name` as subTableName, t.`pri_join_field` as primaryFieldId, t.`sub_join_field` as subFieldId, t.`sub_join_field2` as subFieldId2, priField.field_name as primaryFieldName, subField.field_name as subFieldName, subField2.field_name as subFieldName2, t.`join_type` as joinExpression, t.`join_on_type` as joinOnType, t.`weight`, t.is_active AS isActive, DATE_FORMAT( t.created_time, '%Y-%m-%d %H:%i:%s' ) AS createdTime, DATE_FORMAT( t.updated_time, '%Y-%m-%d %H:%i:%s' ) AS updatedTime, t.created_by AS createdBy, t.updated_by AS updatedBy FROM ssd_table_rel t INNER JOIN ssd_table_def pri ON t.`pri_table_id` = pri.`table_id` INNER JOIN ssd_table_def sub ON t.`sub_table_id` = sub.`table_id` inner join ssd_field_def priField on t.`pri_join_field` = priField.field_id inner join ssd_field_def subField on t.`sub_join_field` = subField.field_id left join ssd_field_def subField2 on t.`sub_join_field2` = subField2.field_id WHERE 1 = 1
ORDER BY ${sortKey} ${sortType}
ORDER BY t.created_time desc
LIMIT ${pageRowLower}, ${prePageSize}

